    "C199", "C218", "C222", "C239", "C195", "C200", "C233", "C208", "C196"
  ],
  "claims": [
    {
      "claim": "Direct L1/L2 gold-context records report absolute oral bioavailability below 20% for multiple transferable steroid contexts: testosterone 3.6 ± 2.5%, testosterone undecanoate 6.8 ± 3.3%, abiraterone acetate <10% fasted, mometasone <1%, fulvestrant poor/not orally bioavailable, and thienorphine very low.",
      "card_ids": ["C34", "C18", "C02", "C17", "C13", "C31", "C16", "C07", "C29", "C70", "C24"]
    },
    {
      "claim": "L3 oral exposure for estradiol-like steroids is low: unconjugated estradiol Cmax 13.3 pg/mL after 0.625 mg Cenestin and 43.66 pg/mL after 2 mg estradiol/norgestimate, consistent with extensive first-pass loss.",
      "card_ids": ["C111", "C99", "C100"]
    },
    {
      "claim": "L4 shows estradiol has very low aqueous solubility, with qualitative very low water solubility and apparent solubility 1.81 ± 0.19 µg/mL in buffer, supporting solubility-limited absorption for the lipophilic estradiol-like query.",
      "card_ids": ["C146", "C188"]
    },
    {
      "claim": "L5 shows estradiol undergoes intestinal Phase II metabolism via glucuronidation/sulfation, with intestinal UGT activity reported, and estrone, ethinylestradiol, and estriol are P-gp efflux substrates; this provides mechanistic evidence for presystemic loss in the estradiol-like query.",
      "card_ids": ["C199", "C218", "C222", "C239", "C195", "C200", "C233", "C208", "C196"]
    },
    {
      "claim": "High Caco-2 permeability for testosterone does not overcome its low absolute oral bioavailability of 3.6%, so high permeability alone is insufficient to establish F ≥ 20%.",
      "card_ids": ["C168", "C183", "C161", "C180", "C191", "C34", "C18"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "gut_wall_efflux_intestinal_metabolism",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C199", "C218", "C222", "C239", "C195", "C200", "C233", "C208", "C196"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement exists for the query molecule.",
    "The query's C17 tertiary hydroxyl and extra-ring substitution are not represented in any direct F record.",
    "L5 provides mechanistic efflux/metabolism data for estradiol, estrone, and ethinylestradiol, not for the query itself; transfer is structural inference.",
    "No human intestinal or hepatic first-pass data specific to the query are available.",
    "Solubility of the query is inferred from estradiol-like analogs, not measured directly."
  ],
  "decision_summary": "L5 gut-wall efflux and intestinal-metabolism evidence supports presystemic loss for the estradiol-like query. Combined with direct low absolute oral bioavailability values from L1/L2 steroid contexts and low estradiol exposure/solubility from L3/L4, F < 20% remains better supported. Prediction low, confidence high."
}

